-- TEST ONLY: correct transport text encoding; no economic or ownership changes.
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
DO $repair$
DECLARE changed integer;
BEGIN
 IF current_setting('fixprod003.target_project',true) IS DISTINCT FROM 'wkdvdzfkbwvhyjmamrsg' THEN RAISE EXCEPTION 'Verified TEST target required'; END IF;
 WITH corrections(id,previous,corrected) AS (VALUES
('arena-card-basic-attack','{"duration":"Um ataque aceito; b\u00c3\u00b4nus preparados s\u00c3\u00a3o consumidos quando o ataque \u00c3\u00a9 executado.","headline":"Ataque b\u00c3\u00a1sico \u00c2\u00b7 at\u00c3\u00a9 +1 Foco","condition":"Carta selecionada, ainda n\u00c3\u00a3o usada; batalha aberta e rodada atual.","focusCost":0,"explanation":"Ao executar, gera at\u00c3\u00a9 1 Foco, limitado a 3; se cair antes de agir, n\u00c3\u00a3o gera Foco. Parcela ofensiva = 3 + 2,2 \u00c3\u2014 For\u00c3\u00a7a + 0,18 \u00c3\u2014 soma do poder de todos os itens equipados. Subtrai 1,15 \u00c3\u2014 Defesa do alvo; aplica multiplicadores e arredonda ao inteiro mais pr\u00c3\u00b3ximo, m\u00c3\u00adnimo 1. Atributos e poder de cada item limitados a 0\u00e2\u20ac\u201c999. Guarda/armadura arredondam para cima em etapas; esquiva causa 0 e dano aplicado n\u00c3\u00a3o ultrapassa o HP restante.","minimumLevel":1}'::jsonb,'{"focusCost":0,"minimumLevel":1,"condition":"Carta selecionada, ainda n\u00e3o usada; batalha aberta e rodada atual.","headline":"Ataque b\u00e1sico \u00b7 at\u00e9 +1 Foco","explanation":"Ao executar, gera at\u00e9 1 Foco, limitado a 3; se cair antes de agir, n\u00e3o gera Foco. Parcela ofensiva = 3 + 2,2 \u00d7 For\u00e7a + 0,18 \u00d7 soma do poder de todos os itens equipados. Subtrai 1,15 \u00d7 Defesa do alvo; aplica multiplicadores e arredonda ao inteiro mais pr\u00f3ximo, m\u00ednimo 1. Atributos e poder de cada item limitados a 0\u2013999. Guarda/armadura arredondam para cima em etapas; esquiva causa 0 e dano aplicado n\u00e3o ultrapassa o HP restante.","duration":"Um ataque aceito; b\u00f4nus preparados s\u00e3o consumidos quando o ataque \u00e9 executado."}'::jsonb),
('arena-card-basic-defense','{"duration":"At\u00c3\u00a9 receber um golpe n\u00c3\u00a3o esquivado; sem prazo fixo em turnos. N\u00c3\u00a3o substitui uma Guarda forte j\u00c3\u00a1 preparada.","headline":"Dano recebido \u00c3\u20140,5 \u00c2\u00b7 at\u00c3\u00a9 +1 Foco","condition":"Carta selecionada, ainda n\u00c3\u00a3o usada; batalha aberta e rodada atual.","focusCost":0,"explanation":"Gera at\u00c3\u00a9 1 Foco, limitado a 3. Aplica \u00c3\u20140,5 ao dano j\u00c3\u00a1 arredondado do pr\u00c3\u00b3ximo golpe recebido. Arredonda para cima, m\u00c3\u00adnimo 1; a redu\u00c3\u00a7\u00c3\u00a3o final pode variar pelo arredondamento. N\u00c3\u00a3o soma Defesa nem cura. A armadura pode multiplicar a prote\u00c3\u00a7\u00c3\u00a3o depois.","minimumLevel":1}'::jsonb,'{"focusCost":0,"minimumLevel":1,"condition":"Carta selecionada, ainda n\u00e3o usada; batalha aberta e rodada atual.","headline":"Dano recebido \u00d70,5 \u00b7 at\u00e9 +1 Foco","explanation":"Gera at\u00e9 1 Foco, limitado a 3. Aplica \u00d70,5 ao dano j\u00e1 arredondado do pr\u00f3ximo golpe recebido. Arredonda para cima, m\u00ednimo 1; a redu\u00e7\u00e3o final pode variar pelo arredondamento. N\u00e3o soma Defesa nem cura. A armadura pode multiplicar a prote\u00e7\u00e3o depois.","duration":"At\u00e9 receber um golpe n\u00e3o esquivado; sem prazo fixo em turnos. N\u00e3o substitui uma Guarda forte j\u00e1 preparada."}'::jsonb),
('arena-card-path-strike','{"duration":"Um ataque; carta consumida ap\u00c3\u00b3s aceite. Se cair antes de agir, o turno aceito ainda gasta a carta.","headline":"Golpe \u00c3\u20141,45","condition":"Carta selecionada, ainda n\u00c3\u00a3o usada; batalha aberta e rodada atual.","focusCost":2,"explanation":"Multiplica por 1,45 a parcela ofensiva menos a Defesa, antes do arredondamento e da guarda. N\u00c3\u00a3o \u00c3\u00a9 percentual da vida do alvo. Modificador de pot\u00c3\u00aancia do snapshot: \u00c3\u20141. Refor\u00c3\u00a7os da espada e vantagem preparada podem multiplicar esse resultado.","minimumLevel":2}'::jsonb,'{"focusCost":2,"minimumLevel":2,"condition":"Carta selecionada, ainda n\u00e3o usada; batalha aberta e rodada atual.","headline":"Golpe \u00d71,45","explanation":"Multiplica por 1,45 a parcela ofensiva menos a Defesa, antes do arredondamento e da guarda. N\u00e3o \u00e9 percentual da vida do alvo. Modificador de pot\u00eancia do snapshot: \u00d71. Refor\u00e7os da espada e vantagem preparada podem multiplicar esse resultado.","duration":"Um ataque; carta consumida ap\u00f3s aceite. Se cair antes de agir, o turno aceito ainda gasta a carta."}'::jsonb),
('arena-card-steadfast-guard','{"duration":"Pr\u00c3\u00b3ximo golpe n\u00c3\u00a3o esquivado; permanece preparada at\u00c3\u00a9 esse golpe, sem prazo fixo em turnos.","headline":"Pr\u00c3\u00b3ximo dano recebido \u00c3\u20140,25","condition":"Carta selecionada, ainda n\u00c3\u00a3o usada; batalha aberta e rodada atual.","focusCost":2,"explanation":"Guarda preparada antes da iniciativa; aplica \u00c3\u20140,25 ao dano j\u00c3\u00a1 arredondado, no lugar da defesa b\u00c3\u00a1sica \u00c3\u20140,5. Arredonda para cima, m\u00c3\u00adnimo 1; a redu\u00c3\u00a7\u00c3\u00a3o final pode variar pelo arredondamento. O escudo n\u00c3\u00a3o acrescenta outro multiplicador.","minimumLevel":4}'::jsonb,'{"focusCost":2,"minimumLevel":4,"condition":"Carta selecionada, ainda n\u00e3o usada; batalha aberta e rodada atual.","headline":"Pr\u00f3ximo dano recebido \u00d70,25","explanation":"Guarda preparada antes da iniciativa; aplica \u00d70,25 ao dano j\u00e1 arredondado, no lugar da defesa b\u00e1sica \u00d70,5. Arredonda para cima, m\u00ednimo 1; a redu\u00e7\u00e3o final pode variar pelo arredondamento. O escudo n\u00e3o acrescenta outro multiplicador.","duration":"Pr\u00f3ximo golpe n\u00e3o esquivado; permanece preparada at\u00e9 esse golpe, sem prazo fixo em turnos."}'::jsonb),
('arena-card-discernment','{"duration":"Pr\u00c3\u00b3ximo ataque executado, b\u00c3\u00a1sico ou Golpe; substitui a vantagem anterior, n\u00c3\u00a3o acumula. Defesa n\u00c3\u00a3o a consome.","headline":"Pr\u00c3\u00b3ximo ataque at\u00c3\u00a9 \u00c3\u20141,55","condition":"Carta selecionada, ainda n\u00c3\u00a3o usada; batalha aberta e rodada atual.","focusCost":2,"explanation":"Prepara multiplicador 1,18 + 0,035 \u00c3\u2014 Sabedoria, limitado a 1,55. Aplica sobre a parcela ofensiva menos a Defesa, antes do arredondamento. Revela somente a inten\u00c3\u00a7\u00c3\u00a3o prov\u00c3\u00a1vel permitida pela mec\u00c3\u00a2nica ap\u00c3\u00b3s o uso.","minimumLevel":6}'::jsonb,'{"focusCost":2,"minimumLevel":6,"condition":"Carta selecionada, ainda n\u00e3o usada; batalha aberta e rodada atual.","headline":"Pr\u00f3ximo ataque at\u00e9 \u00d71,55","explanation":"Prepara multiplicador 1,18 + 0,035 \u00d7 Sabedoria, limitado a 1,55. Aplica sobre a parcela ofensiva menos a Defesa, antes do arredondamento. Revela somente a inten\u00e7\u00e3o prov\u00e1vel permitida pela mec\u00e2nica ap\u00f3s o uso.","duration":"Pr\u00f3ximo ataque executado, b\u00e1sico ou Golpe; substitui a vantagem anterior, n\u00e3o acumula. Defesa n\u00e3o a consome."}'::jsonb),
('arena-card-pilgrim-step','{"duration":"Um golpe recebido; permanece at\u00c3\u00a9 ocorrer, sem prazo fixo em turnos. N\u00c3\u00a3o acumula esquivas ao repetir.","headline":"Evita o pr\u00c3\u00b3ximo golpe recebido \u00c2\u00b7 dano 0","condition":"Carta selecionada, ainda n\u00c3\u00a3o usada; batalha aberta e rodada atual.","focusCost":3,"explanation":"Prepara uma esquiva garantida para um golpe recebido; n\u00c3\u00a3o usa probabilidade nem recupera vida. Tem prioridade sobre o uso autom\u00c3\u00a1tico das botas.","minimumLevel":8}'::jsonb,'{"focusCost":3,"minimumLevel":8,"condition":"Carta selecionada, ainda n\u00e3o usada; batalha aberta e rodada atual.","headline":"Evita o pr\u00f3ximo golpe recebido \u00b7 dano 0","explanation":"Prepara uma esquiva garantida para um golpe recebido; n\u00e3o usa probabilidade nem recupera vida. Tem prioridade sobre o uso autom\u00e1tico das botas.","duration":"Um golpe recebido; permanece at\u00e9 ocorrer, sem prazo fixo em turnos. N\u00e3o acumula esquivas ao repetir."}'::jsonb),
('arena-card-measured-strike','{"duration":"Um ataque; uma utiliza\u00c3\u00a7\u00c3\u00a3o por batalha. Carta consumida somente ap\u00c3\u00b3s comando aceito, mesmo se cair antes de agir. Permanece na cole\u00c3\u00a7\u00c3\u00a3o e volta na pr\u00c3\u00b3xima batalha.","headline":"Golpe Medido \u00c3\u20141,15","condition":"Carta selecionada, ainda n\u00c3\u00a3o usada; batalha aberta e rodada atual.","focusCost":1,"explanation":"Multiplica por 1,15 a parcela ofensiva menos a Defesa, antes do arredondamento e da guarda. N\u00c3\u00a3o \u00c3\u00a9 aumento fixo do dano final nem percentual da vida. Modificador de pot\u00c3\u00aancia do snapshot: \u00c3\u20141. Vantagem preparada e b\u00c3\u00b4nus da espada ap\u00c3\u00b3s Defender continuam aplic\u00c3\u00a1veis; o refor\u00c3\u00a7o ativo exclusivo do Golpe do Caminho n\u00c3\u00a3o \u00c3\u00a9 ativado. N\u00c3\u00a3o gera Foco; descontos respeitam o piso de 1 Foco.","minimumLevel":1}'::jsonb,'{"focusCost":1,"minimumLevel":1,"condition":"Carta selecionada, ainda n\u00e3o usada; batalha aberta e rodada atual.","headline":"Golpe Medido \u00d71,15","explanation":"Multiplica por 1,15 a parcela ofensiva menos a Defesa, antes do arredondamento e da guarda. N\u00e3o \u00e9 aumento fixo do dano final nem percentual da vida. Modificador de pot\u00eancia do snapshot: \u00d71. Vantagem preparada e b\u00f4nus da espada ap\u00f3s Defender continuam aplic\u00e1veis; o refor\u00e7o ativo exclusivo do Golpe do Caminho n\u00e3o \u00e9 ativado. N\u00e3o gera Foco; descontos respeitam o piso de 1 Foco.","duration":"Um ataque; uma utiliza\u00e7\u00e3o por batalha. Carta consumida somente ap\u00f3s comando aceito, mesmo se cair antes de agir. Permanece na cole\u00e7\u00e3o e volta na pr\u00f3xima batalha."}'::jsonb)
 ) UPDATE economy_private.card_catalog c SET definition=jsonb_set(c.definition,'{description}',r.corrected)
 FROM corrections r WHERE c.id=r.id AND c.version='arena-cards-2026-10-20.2-fixprod003-test'
 AND c.approval_ref='FIX-PROD-003:TEST-ONLY:2026-10-23' AND c.definition->'description'=r.previous;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>7 THEN RAISE EXCEPTION 'Unexpected text baseline'; END IF;
END $repair$;
